/**
 * Unit tests for MutableDateTime.addHours(int).
 */
public class MutableDateTime_addHours_TriageGen2Test {

    @Test
    public void testAddHours_PositiveValue() {
        // Initialize at 2023-01-01 10:00:00
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);

        // Add 5 hours
        dt.addHours(5);

        // Verify result is 2023-01-01 15:00:00
        Assert.assertEquals(15, dt.getHourOfDay());
    }

    @Test
    public void testAddHours_NegativeValue() {
        // Initialize at 2023-01-01 10:00:00
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);

        // Subtract 5 hours
        dt.addHours(-5);

        // Verify result is 2023-01-01 05:00:00
        Assert.assertEquals(5, dt.getHourOfDay());
    }

    @Test
    public void testAddHours_ZeroValue() {
        // Initialize at 2023-01-01 10:00:00
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);

        // Add 0 hours (This covers the 'if (hours != 0)' branch condition being false)
        dt.addHours(0);

        // Verify time remains unchanged
        Assert.assertEquals(10, dt.getHourOfDay());
    }

    @Test
    public void testAddHours_OverflowDay() {
        // Initialize at 2023-01-01 22:00:00
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 22, 0, 0, 0);

        // Add 4 hours to cross midnight
        dt.addHours(4);

        // Verify result is 2023-01-02 02:00:00
        Assert.assertEquals(2, dt.getDayOfMonth());
        Assert.assertEquals(2, dt.getHourOfDay());
    }

    @Test
    public void testAddHours_LargeValue() {
        // Initialize at 2023-01-01 00:00:00
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);

        // Add 48 hours (2 full days)
        dt.addHours(48);

        // Verify result is 2023-01-03 00:00:00
        Assert.assertEquals(3, dt.getDayOfMonth());
        Assert.assertEquals(0, dt.getHourOfDay());
    }
}
